// Each person shows their rung: (their group's size less their standing in it) over the group's size, as a
// percentage, rounded; a group of one is 100 ("n/a" without a standing).
// Each person shows their depth: their standing in their group less one ("n/a" without a standing).
// Each person shows their anchorage: how many groups they belong to (0 without one).
// Each person shows their home group: the name of their group ("n/a" without one).
// Each person shows their anchor strength: the strength of their home group ("n/a" without one).
// Each person shows their group rank: the rank of their home group by strength ("n/a" without one).
// Each person shows their anchor cohesion: the cohesion of their home group ("n/a" without one).
// Each person shows their reach span: their home group's strength ("n/a" without one).
// Each person shows their global rank: their place among everyone on the sheet by scaled, highest
// first (1), with equal scaled placed by name ("n/a" while their scaled is "n/a").
// Each person shows their bracket: the quartile of their scaled — Q4 from 800, Q3 from 200 to 799,
// Q2 from 50 to 199 and Q1 below 50 ("n/a" while their scaled is "n/a").
// Each person shows their cume: going down the global rank, the scaled of everyone so far added
// together, their own included ("n/a" while their scaled is "n/a").
// The sheet's strongest member is the name of the person with the highest scaled anywhere on the sheet,
// ties going to the name earlier in the alphabet ("n/a" when nobody has a scaled).
// The sheet's apex name is the name of the person with the highest scaled anywhere on the sheet, and its
// runner-up the name of the second highest, ties going to the name earlier in the alphabet ("n/a" when
// there is no such person).
// The sheet's top set is the names of the three people with the highest scaled, highest first, ties
// going to the name earlier in the alphabet, joined by commas (fewer when fewer have a scaled; "n/a"
// when nobody has one).
// The sheet's gap is the highest scaled on the sheet minus the lowest ("n/a" when fewer than two
// people have a scaled).
// The sheet's range is the highest scaled on the sheet minus the lowest ("n/a" when nobody has a scaled).
// The sheet's median scaled is the middle of the scaled of everyone on the sheet whose scaled can be
// worked out; for an even count, the lower of the two middle values ("n/a" when nobody has a scaled).
// The sheet's coverage is how many of its people have a scaled of at least 500 (0 when nobody does).
// The sheet's concentration is the scaled of its three highest-scaled people added together as a percentage
// of its ledger, rounded down ("n/a" when the ledger is zero).
// The sheet's skew is the average scaled, rounded down, minus its median scaled, of everyone whose scaled
// can be worked out ("n/a" when nobody has a scaled).
// The sheet's digest is the average scaled, rounded down, of everyone whose scaled can be worked out
// ("n/a" when nobody has a scaled).
// The sheet's tilt is how many people have a scaled above the median scaled minus how many have one
// below it, of everyone whose scaled can be worked out (0 when nobody has a scaled).
// A person may be in several groups; a group's figures count every person in it. Where a person's own
// figure depends on "their group", it is the group, of those they are in, whose name comes first
// alphabetically.
@Component({
  selector: 'app-people',
  imports: [ReactiveFormsModule],
  template: `
    <h1>People</h1>

    <form (submit)="$event.preventDefault(); openSheet(sheetInput.value)" data-testid="sheet-form">
      <label for="sheet-id">Sheet</label>
      <input #sheetInput id="sheet-id" data-testid="sheet-id-input" />
      <button type="submit" data-testid="sheet-load">Open sheet</button>
    </form>
    <p>Grand flow: <strong data-testid="rollup-grand-flow">{{ grandFlow() }}</strong></p>
    <p>Top flow: <strong data-testid="rollup-top-flow">{{ topFlow() ?? 'n/a' }}</strong></p>
    <p>Outliers: <strong data-testid="rollup-outlier-count">{{ outlierCount() }}</strong></p>
    <p>Strays: <strong data-testid="rollup-stray-count">{{ strayCount() }}</strong></p>
    <p>Meeting quota: <strong data-testid="rollup-quota-count">{{ quotaCount() }}</strong></p>
    <p>Final total: <strong data-testid="rollup-final-total">{{ finalTotal() }}</strong></p>
    <p>Ledger: <strong data-testid="rollup-ledger">{{ ledger() }}</strong></p>
    <p>Strongest member: <strong data-testid="rollup-strongest-member">{{ strongestMember() ?? 'n/a' }}</strong></p>
    <p>Apex: <strong data-testid="rollup-apexname">{{ apexName() ?? 'n/a' }}</strong></p>
    <p>Runner-up: <strong data-testid="rollup-runnerup">{{ runnerUp() ?? 'n/a' }}</strong></p>
    <p>Top three: <strong data-testid="rollup-topset">{{ topSet() ?? 'n/a' }}</strong></p>
    <p>Gap: <strong data-testid="rollup-gapval">{{ gapVal() ?? 'n/a' }}</strong></p>
    <p>Range: <strong data-testid="rollup-range-scaled">{{ rangeScaled() ?? 'n/a' }}</strong></p>
    <p>Median scaled: <strong data-testid="rollup-median-scaled">{{ medianScaled() ?? 'n/a' }}</strong></p>
    <p>Coverage (scaled 500 or more): <strong data-testid="rollup-coverage">{{ coverage() }}</strong></p>
    <p>Concentration (top three share %): <strong data-testid="rollup-concentration">{{ concentration() ?? 'n/a' }}</strong></p>
    <p>Bands in use: <strong data-testid="rollup-spanwidth">{{ spanWidth() }}</strong></p>
    <p>Skew (average minus median scaled): <strong data-testid="rollup-skewval">{{ skewVal() ?? 'n/a' }}</strong></p>
    <p>Digest (average scaled per person): <strong data-testid="rollup-digest">{{ digest() ?? 'n/a' }}</strong></p>
    <p>Tilt (above median minus below median scaled): <strong data-testid="rollup-tilt">{{ tilt() }}</strong></p>
    <section aria-labelledby="region-counts-heading">
      <h2 id="region-counts-heading">People per region</h2>
      @if (regionCounts().length === 0) {
        <p>No regions yet.</p>
      } @else {
        <ul>
  protected readonly totalBrace = computed(() =>
    this.people().reduce((total, p) => total + (p.brace ?? 0), 0),
  );
  protected readonly totalYield = computed(() =>
    this.people().reduce((total, p) => total + (p.yield ?? 0), 0),
  );
  protected readonly totalTide = computed(() =>
    this.people().reduce((total, p) => total + (p.tide ?? 0), 0),
  );
  protected readonly grandFlow = computed(() =>
    this.people().reduce((total, p) => total + (p.flow ?? 0), 0),
  );
  protected readonly finalTotal = computed(() =>
    this.people()
      .filter((p) => p.state === 'FINAL')
      .reduce((total, p) => total + (p.scaled ?? 0), 0),
  );
  protected readonly ledger = computed(() =>
    this.people().reduce((total, p) => total + (p.scaled ?? 0), 0),
  );
  protected readonly coverage = computed(
    () => this.people().filter((p) => p.scaled !== null && p.scaled >= 500).length,
  );
  protected readonly groupStrengths = computed(() => {
    const strengths = new Map<number, number>();
    for (const p of this.people()) {
      for (const g of p.groups) strengths.set(g.id, (strengths.get(g.id) ?? 0) + (p.effective ?? 0));
    }
    return strengths;
  });
  protected readonly totalStrength = computed(() => {
    const strengths = this.groupStrengths();
    return this.groups().reduce((total, g) => total + (strengths.get(g.id) ?? 0), 0);
  });
  protected readonly groupCount = computed(() => this.groups().length);
  protected readonly meanSize = computed(() => {
    const sizes = this.groupSizes();
    const groups = this.groups();
    if (groups.length === 0) return null;
    return Math.floor(groups.reduce((total, g) => total + (sizes.get(g.id) ?? 0), 0) / groups.length);
  });
